TENANT_TABLES = [
    "memberships", "access_grants", "invitations", "audit_log", "clients", "contacts", "brands", "domains",
    "projects", "project_markets", "competitors", "notes",
]
GLOBAL_RW_TABLES = ["users", "sessions", "password_reset_tokens"]
APP_ROLE = "aisv_app"
CUR_TENANT = "NULLIF(current_setting('app.tenant_id', true), '')::uuid"
CUR_USER = "NULLIF(current_setting('app.user_id', true), '')::uuid"

MARKETS = [
    ("US", "United States"), ("GB", "United Kingdom"), ("CA", "Canada"), ("AU", "Australia"),
    ("IE", "Ireland"), ("NZ", "New Zealand"), ("DE", "Germany"), ("FR", "France"), ("ES", "Spain"),
    ("IT", "Italy"), ("NL", "Netherlands"), ("SE", "Sweden"), ("DK", "Denmark"), ("NO", "Norway"),
    ("FI", "Finland"), ("PL", "Poland"), ("PT", "Portugal"), ("BR", "Brazil"), ("MX", "Mexico"),
    ("IN", "India"), ("SG", "Singapore"), ("JP", "Japan"), ("AE", "United Arab Emirates"),
    ("ZA", "South Africa"), ("BD", "Bangladesh"),
]
LANGUAGES = [
    ("en", "English"), ("de", "German"), ("fr", "French"), ("es", "Spanish"), ("it", "Italian"),
    ("nl", "Dutch"), ("sv", "Swedish"), ("da", "Danish"), ("nb", "Norwegian Bokmal"), ("fi", "Finnish"),
    ("pl", "Polish"), ("pt", "Portuguese"), ("ja", "Japanese"), ("ar", "Arabic"), ("hi", "Hindi"),
    ("bn", "Bengali"),
]


def _security_upgrade() -> None:
    # --- Grants: runtime role gets only what it needs. ---
    for t in TENANT_TABLES:
        if t == "audit_log":
            op.execute(f"GRANT SELECT, INSERT ON {t} TO {APP_ROLE}")  # append-only
        else:
            op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON {t} TO {APP_ROLE}")
    for t in GLOBAL_RW_TABLES:
        op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON {t} TO {APP_ROLE}")
    op.execute(f"GRANT SELECT, INSERT ON access_events TO {APP_ROLE}")  # append-only
    op.execute(f"GRANT SELECT, INSERT, UPDATE ON tenants TO {APP_ROLE}")
    op.execute(f"GRANT SELECT ON markets, languages TO {APP_ROLE}")

    # --- Row-level security on every tenant-owned table. ---
    for t in TENANT_TABLES:
        op.execute(f"ALTER TABLE {t} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {t} FORCE ROW LEVEL SECURITY")
        op.execute(
            f"CREATE POLICY tenant_isolation ON {t} USING (tenant_id = {CUR_TENANT}) "
            f"WITH CHECK (tenant_id = {CUR_TENANT})"
        )
    # A user may also read their OWN memberships across tenants (tenant switcher, login).
    op.execute(f"CREATE POLICY own_memberships ON memberships FOR SELECT USING (user_id = {CUR_USER})")

    # Tenants: visible if current tenant, or the current user has a membership in it.
    op.execute("ALTER TABLE tenants ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE tenants FORCE ROW LEVEL SECURITY")
    op.execute(
        f"CREATE POLICY tenant_read ON tenants FOR SELECT USING (id = {CUR_TENANT} OR EXISTS "
        f"(SELECT 1 FROM memberships m WHERE m.tenant_id = tenants.id AND m.user_id = {CUR_USER}))"
    )
    op.execute(f"CREATE POLICY tenant_insert ON tenants FOR INSERT WITH CHECK (id = {CUR_TENANT})")
    op.execute(
        f"CREATE POLICY tenant_update ON tenants FOR UPDATE USING (id = {CUR_TENANT}) WITH CHECK (id = {CUR_TENANT})"
    )

    # Invitation acceptance happens before tenant context exists. This narrow SECURITY DEFINER
    # function resolves ONLY the tenant of a valid, unexpired, unused invitation token hash.
    op.execute(
        """
        CREATE FUNCTION invitation_tenant(p_token_hash text) RETURNS uuid
        LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
            SELECT tenant_id FROM invitations
            WHERE token_hash = p_token_hash AND accepted_at IS NULL AND revoked_at IS NULL
              AND expires_at > now()
        $$
        """
    )
    # FORCE RLS also binds the owner, so the definer function needs an owner-only read policy.
    # The runtime app role is unaffected (policy is TO the migration/owner role only).
    op.execute("CREATE POLICY definer_invitation_lookup ON invitations FOR SELECT TO CURRENT_USER USING (true)")
    op.execute("REVOKE ALL ON FUNCTION invitation_tenant(text) FROM PUBLIC")
    op.execute(f"GRANT EXECUTE ON FUNCTION invitation_tenant(text) TO {APP_ROLE}")

    markets = sa.table("markets", sa.column("code", sa.String), sa.column("name", sa.String))
    languages = sa.table("languages", sa.column("code", sa.String), sa.column("name", sa.String))
    op.bulk_insert(markets, [{"code": c, "name": n} for c, n in MARKETS])
    op.bulk_insert(languages, [{"code": c, "name": n} for c, n in LANGUAGES])


def _security_downgrade() -> None:
    op.execute("DROP FUNCTION IF EXISTS invitation_tenant(text)")
    op.execute("DROP POLICY IF EXISTS definer_invitation_lookup ON invitations")
    op.execute("DROP POLICY IF EXISTS tenant_read ON tenants")
    op.execute("DROP POLICY IF EXISTS tenant_insert ON tenants")
    op.execute("DROP POLICY IF EXISTS tenant_update ON tenants")
    op.execute("DROP POLICY IF EXISTS own_memberships ON memberships")
    for t in TENANT_TABLES:
        op.execute(f"DROP POLICY IF EXISTS tenant_isolation ON {t}")
